SELECT id, supplier_id, stockin_qc_user_name AS stockInQcUserName, stockout_qc_user_name AS stockOutQcUserName, outside_qc_user_name AS outsideQcUserName, inside_qc_user_name AS insideQcUserName, new_product_stockin_qc_user_name AS newProductStockInQcUserName, b2b_outside_qc_user_name AS b2bOutsideQcUserName, return_qc_user_name AS returnQcUserName, create_time, create_user_name, update_time, update_user_name FROM cfg_qc_user WHERE is_deleted = FALSE
